   449	// parseDurationDays extends time.ParseDuration to accept "d" (days) since
   450	// time.ParseDuration tops out at hours ("h").
   451	func parseDurationDays(s string) (time.Duration, error) {
   452		if len(s) > 1 && s[len(s)-1] == 'd' {
   453			n, err := strconv.Atoi(s[:len(s)-1])
   454			if err != nil {
   455				return 0, err
   456			}
   457			return time.Duration(n) * 24 * time.Hour, nil
   458		}
   459		return time.ParseDuration(s)
   460	}
