   462	// fmtInt adds thousand separators to an int for readability.
   463	func fmtInt(n int) string {
   464		s := strconv.Itoa(n)
   465		if len(s) <= 3 {
   466			return s
   467		}
   468		out := ""
   469		for i, c := range s {
   470			if i != 0 && (len(s)-i)%3 == 0 {
   471				out += ","
   472			}
   473			out += string(c)
   474		}
   475		return out
   476	}
