    71		rec   *Recorder
    72	}
    73	
    74	// Start opens a new Span. Use defer span.End() right after.
    75	func (r *Recorder) Start(name string, kind Kind) *Span {
    76		now := time.Now()
    77		return &Span{
    78			event: Event{
    79				ID:        ulid.Make().String(),
    80				Timestamp: now,
    81				Kind:      kind,
    82				Name:      name,
    83			},
    84			start: now,
    85			rec:   r,
    86		}
