    95	// callers can enrich it via FromContext without coordinating a skip list.
    96	// The middleware calls End via defer; handlers only call setters.
    97	func (r *Recorder) StartCtx(ctx context.Context, name string, kind Kind) (context.Context, *Span) {
    98		span := r.Start(name, kind)
    99		return context.WithValue(ctx, spanCtxKey{}, span), span
   100	}
   101	
   102	// StartCtx is a convenience using the default recorder.
   103	func StartCtx(ctx context.Context, name string, kind Kind) (context.Context, *Span) {
