const TRUTHY = new Set(["1", "true", "on", "yes"]);
const FALSY = new Set(["0", "false", "off", "no"]);

/**
 * isTruthy reports whether an env-var value should be treated as "on".
 * Accepts the same set as the Go config helper: 1/true/on/yes
